function groundTex(){const c=document.createElement('canvas');c.width=c.height=1024;const x=c.getContext('2d');x.fillStyle='#8e956e';x.fillRect(0,0,1024,1024);for(let i=0;i<140;i++){const px=Math.random()*1024,py=Math.random()*1024,r=30+Math.random()*100,g=x.createRadialGradient(px,py,0,px,py,r);g.addColorStop(0,i%2?'rgba(80,97,48,.09)':'rgba(190,180,130,.1)');g.addColorStop(1,'rgba(130,140,90,0)');x.fillStyle=g;x.fillRect(px-r,py-r,r*2,r*2);}for(let i=0;i<16000;i++){x.fillStyle=Math.random()>.5?'rgba(225,215,170,.08)':'rgba(50,70,30,.08)';x.fillRect(Math.random()*1024,Math.random()*1024,1,2);}const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(26,26);t.encoding=THREE.sRGBEncoding;t.anisotropy=8;return t;}
