/* ---------- geometry helpers ---------- */
function shapeOf(poly){const s=new THREE.Shape();poly.forEach(([x,z],i)=>i?s.lineTo(x,-z):s.moveTo(x,-z));s.closePath();return s;}
function slab(poly,h,mat,y0=0){const g=new THREE.ExtrudeGeometry(shapeOf(poly),{depth:h,bevelEnabled:false});g.rotateX(-Math.PI/2);g.translate(0,y0,0);
  const m=new THREE.Mesh(g,mat);m.receiveShadow=true;return m;}
function centroid(poly){let a=0,cx=0,cz=0;for(let i=0;i<poly.length;i++){const[x0,z0]=poly[i],[x1,z1]=poly[(i+1)%poly.length];const c=x0*z1-x1*z0;a+=c;cx+=(x0+x1)*c;cz+=(z0+z1)*c;}a/=2;return[cx/(6*a),cz/(6*a),Math.abs(a)];}
function inside(p,poly){let c=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const[xi,zi]=poly[i],[xj,zj]=poly[j];if((zi>p[1])!=(zj>p[1])&&p[0]<(xj-xi)*(p[1]-zi)/(zj-zi)+xi)c=!c;}return c;}
function scalePoly(poly,k,c){return poly.map(([x,z])=>[c[0]+(x-c[0])*k,c[1]+(z-c[1])*k]);}
function edgesOf(mesh,color,op=.5,ang=25){const e=new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry,ang),new THREE.LineBasicMaterial({color,transparent:true,opacity:op}));mesh.add(e);return e;}
function labelTex(text,sub,color){const c=document.createElement("canvas");c.width=256;c.height=160;const x=c.getContext("2d");x.textAlign="center";x.textBaseline="middle";x.fillStyle=color;
  x.font="500 92px 'Cormorant Garamond', Georgia, serif";x.fillText(text,128,sub?64:80);
  if(sub){x.font="400 24px Jost, Arial, sans-serif";x.globalAlpha=.85;x.fillText(sub,128,126);}
  const t=new THREE.CanvasTexture(c);t.encoding=THREE.sRGBEncoding;t.anisotropy=8;return t;}
function flatLabel(text,sub,pos,w,y,color){const m=new THREE.Mesh(new THREE.PlaneGeometry(w,w*160/256),new THREE.MeshBasicMaterial({map:labelTex(text,sub,color),transparent:true,depthWrite:false}));
  m.rotation.x=-Math.PI/2;m.position.set(pos[0],y,pos[1]);m.renderOrder=3;return m;}
const BAKE=new Map();
function bake(...objs){objs.forEach(o=>{o.updateMatrixWorld(true);o.traverse(m=>{if(!m.isMesh)return;let e=BAKE.get(m.material);if(!e){e={geos:[],cast:false};BAKE.set(m.material,e);}
  let g=m.geometry.index?m.geometry.toNonIndexed():m.geometry.clone();g.applyMatrix4(m.matrixWorld);Object.keys(g.attributes).forEach(k=>{if(!["position","normal","uv"].includes(k))g.deleteAttribute(k);});g.clearGroups();e.geos.push(g);e.cast=e.cast||m.castShadow;});});}
function flushBake(){BAKE.forEach((e,mat)=>{const g=THREE.BufferGeometryUtils.mergeBufferGeometries(e.geos,false);e.geos.forEach(x=>x.dispose());const m=new THREE.Mesh(g,mat);m.castShadow=e.cast;m.receiveShadow=true;m.matrixAutoUpdate=false;m.updateMatrix();scene.add(m);});BAKE.clear();}
