function surfTex(base,spots,lines){const c=document.createElement("canvas");c.width=c.height=256;const x=c.getContext("2d");x.fillStyle=base;x.fillRect(0,0,256,256);
  for(let i=0;i<5000;i++){const v=spots[(Math.random()*spots.length)|0];x.fillStyle=v;x.globalAlpha=.25+Math.random()*.35;const s=.8+Math.random()*2.2;x.fillRect(Math.random()*256,Math.random()*256,s,s);}
  if(lines){x.globalAlpha=.07;x.strokeStyle="#000";for(let y=4;y<256;y+=9){x.beginPath();x.moveTo(0,y+Math.random()*2);x.lineTo(256,y+Math.random()*2);x.stroke();}}
  x.globalAlpha=1;const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(1/12,1/12);t.encoding=THREE.sRGBEncoding;t.anisotropy=8;return t;}
