  const near=p=>{let bi=0,bd=1e9;ring.forEach((q,i)=>{const d=Math.hypot(q[0]-p[0],q[1]-p[1]);if(d<bd){bd=d;bi=i;}});return bi;};
  const iw=near(pts[0]),ie=near(pts[pts.length-1]);if(Math.abs(iw-ie)!==1)return ring;const lo=Math.min(iw,ie),hi=Math.max(iw,ie);
  const X=(p1,p2,p3,p4)=>{const d=(p1[0]-p2[0])*(p3[1]-p4[1])-(p1[1]-p2[1])*(p3[0]-p4[0]);if(Math.abs(d)<1e-6)return p2;const t=((p1[0]-p3[0])*(p3[1]-p4[1])-(p1[1]-p3[1])*(p3[0]-p4[0]))/d;return [p1[0]+t*(p2[0]-p1[0]),p1[1]+t*(p2[1]-p1[1])];};
  const n=ring.length;const wPrev=ring[(iw-1+n)%n],ePrev=ring[(ie+1)%n];
  const W1=X(O[1],O[0],wPrev,ring[iw]),E1=X(O[O.length-2],O[O.length-1],ring[ie],ePrev);
