  const pc=document.createElement("canvas");pc.width=1024;pc.height=128;const x2=pc.getContext("2d");x2.fillStyle="#FFE3A8";x2.textAlign="center";x2.textBaseline="middle";x2.font="500 82px 'Cormorant Garamond', Georgia, serif";x2.fillText("A A S T H A",512,70);
  const tx=new THREE.CanvasTexture(pc);tx.encoding=THREE.sRGBEncoding;tx.anisotropy=8;const signMat=new THREE.MeshBasicMaterial({map:tx,transparent:true,depthWrite:false,color:0xffffff});
  [1,-1].forEach(f=>{const m=new THREE.Mesh(new THREE.PlaneGeometry(9,1.12),signMat);const [x,z]=P(0,f*.57);m.position.set(x,6.35,z);m.rotation.y=Math.atan2(nrm[0]*f,nrm[1]*f);G.add(m);});
