      add(slab(box(w,.12,0,oz-d/2-1.75),1.05,BM.bronze,y+.25));                  // gallery railing
      const nf=Math.round(w/2.4);for(let i=0;i<=nf;i++)add(slab(box(.16,.5,-w/2+i*w/nf,oz+d/2+.25),FH-.3,BM.timber,y+.3)); // timber fins on the private face
