  for(let i=0;i<11;i++){const x=-20+i*4;add(slab(box(.12,5,x,10.2),.02,BM.stripe,base+.04));}
  add(slab(box(40,.12,0,7.7),.02,BM.stripe,base+.04));
  for(let i=0;i<5;i++){const x=-18+i*2.7;add(slab(box(.1,4.6,x,-4.5),.02,BM.stripe,base+.04));}   // stilt bays under west wing
  [[-22,-12],[22,-12],[-22,12],[22,12],[0,-12.6],[-12,12.8],[12,12.8]].forEach(([x,z])=>{const [wx,wz]=L2W(x,z);const t=new THREE.Mesh(new THREE.CylinderGeometry(.15,.2,2.4,6),M.trunk);t.position.set(wx,base+1.2,wz);add(t);const c=new THREE.Mesh(new THREE.IcosahedronGeometry(1.8,1),BM.green);c.position.set(wx,base+3.2,wz);c.castShadow=true;add(c);});
  // ground + retail floors: tall storefront glazing with white slab edges
  for(let i=0;i<3;i++){const y=Y[i],h=CINEMA_FLOORS[i].h;
    [W,E].forEach(B=>{add(slab(box(B.w+.6,B.d+.6,B.x,B.z),.35,BM.white,y));if(!(i===0&&B===W))add(slab(box(B.w,B.d,B.x,B.z),h-.35,M.bGlass,y+.35));
      for(let k=0;k<=4;k++)add(slab(box(.2,.2,B.x-B.w/2+k*B.w/4,B.z-B.d/2-.05),h-.35,BM.dark,y+.35));});
    add(slab(box(C.w,C.d,C.x,C.z),h,BM.stone,y));}
  // west wing ground = stilt (columns only)
  [[-1,-1],[1,-1],[-1,1],[1,1]].forEach(([a,b])=>add(slab(box(.5,.5,W.x+a*W.w*.45,W.z+b*W.d*.4),Y[1]-base,BM.dark,base)));
  // cinema floors: solid bronze-clad theatre box, cantilevered, with gold fins; glazed cafeteria on the west wing
  const T={w:E.w+1.6,d:E.d+1.4,x:E.x+.4,z:E.z};
  add(slab(box(T.w,T.d,T.x,T.z),top-Y[3],BM.bronze,Y[3]));
  for(let k=0;k<14;k++)add(slab(box(.18,.5,T.x-T.w/2+.5+k*(T.w-1)/13,T.z-T.d/2-.25),top-Y[3]-.6,BM.gold,Y[3]+.3));
  add(slab(box(T.w+.8,T.d+.8,T.x,T.z),.5,BM.dark,top));
  for(let i=3;i<5;i++){const y=Y[i],h=CINEMA_FLOORS[i].h;add(slab(box(W.w+.6,W.d+.6,W.x,W.z),.35,BM.white,y));add(slab(box(W.w,W.d,W.x,W.z),h-.35,M.bGlass,y+.35));add(slab(box(C.w,C.d,C.x,C.z),h,BM.stone,y));}
  add(slab(box(W.w,1.6,W.x,W.z-W.d/2-.8),.25,BM.white,Y[3]));add(slab(box(W.w,.06,W.x,W.z-W.d/2-1.6),1.05,BM.rail,Y[3]+.25));   // 5 ft balcony
  add(slab(box(W.w+.6,W.d+.6,W.x,W.z),.5,BM.white,top));add(slab(box(C.w,C.d,C.x,C.z),.5,BM.white,top));
  add(slab(box(4,5,C.x+2,C.z),3,BM.stone,top+.5));                                      // lift overrun
  // entrance canopy + double-height foyer glazing on the north face
  add(slab(box(10,5,C.x+1,C.z-C.d/2-2.6),.25,BM.white,Y[1]-.2));
  [[-4.5,-4.9],[4.5,-4.9]].forEach(([x,z])=>{const [wx,wz]=L2W(C.x+1+x,C.z-C.d/2-2.6+z*.4);const c=new THREE.Mesh(new THREE.CylinderGeometry(.16,.16,Y[1]-base,8),BM.dark);c.position.set(wx,base+(Y[1]-base)/2,wz);add(c);});
