/* ================= Floor plan configurations ================= */
const UNIT={1:{n:"1 BHK",c:"#6f6452",sz:480},2:{n:"2 BHK",c:"#9a8458",sz:760},3:{n:"3 BHK",c:"#c8a96e",sz:1100},4:{n:"4 BHK",c:"#e6cf97",sz:1600}};
const EFF=.72;
function mixes(carpet){
  const out=[];const fit=(types,name,line)=>{ // repeat the pattern until it no longer fits, then scale to fill
    let list=[],sum=0,i=0;while(true){const t=types[i%types.length];if(sum+UNIT[t].sz>carpet*1.15)break;list.push(t);sum+=UNIT[t].sz;i++;if(list.length>10)break;}
    if(list.length<1)return;const k=carpet/sum;out.push({name,line,units:list.map(t=>({t,a:Math.round(UNIT[t].sz*k/10)*10}))});};
  fit([3],"Family","Every home a three-bedroom");
  fit([3,2],"Balanced","A mix of two and three bedrooms");
  fit([2,1],"Investor","Compact homes with strong rental demand");
  const big=Math.max(1,Math.min(2,Math.floor(carpet/1500)));out.push({name:big===1?"Full floor":"Signature",line:big===1?"One residence per floor":"Two large residences per floor",units:Array.from({length:big},()=>({t:4,a:Math.round(carpet/big/10)*10}))});
  // de-duplicate identical mixes
  const seen=new Set();return out.filter(m=>{const k=m.units.map(u=>u.t).sort().join("");if(seen.has(k))return false;seen.add(k);return true;});
}
function cellsRect(x,y,w,h,units){ // two rows split by a central corridor; core in the middle
  const n=units.length,cells=[];const cw=h*.14;
  if(n<=2){const tot=units.reduce((s,u)=>s+u.a,0);let cx=x;units.forEach(u=>{const ww=w*u.a/tot;cells.push({x:cx,y,w:ww,h,u,side:"top"});cx+=ww;});return {cells,cores:[{x:x+w/2-w*.09,y:y+h/2-h*.16,w:w*.18,h:h*.32}],corr:null};}
  const top=units.slice(0,Math.ceil(n/2)),bot=units.slice(Math.ceil(n/2));const rh=(h-cw)/2;
  [[top,y,"top"],[bot,y+rh+cw,"bottom"]].forEach(([row,yy,sd])=>{const tot=row.reduce((s,u)=>s+u.a,0);let cx=x;row.forEach(u=>{const ww=w*u.a/tot;cells.push({x:cx,y:yy,w:ww,h:rh,u,side:sd});cx+=ww;});});
  return {cells,cores:[{x:x+w/2-w*.08,y:y+rh-h*.04,w:w*.16,h:cw+h*.08}],corr:{x,y:y+rh,w,h:cw}};
}
function roomsSVG(c){
  const sd=c.side||"top",horiz=sd==="top"||sd==="bottom";const L=horiz?c.w:c.h,Dp=horiz?c.h:c.w;if(L<40||Dp<30)return "";
  const R=(l0,l1,d0,d1)=>{let x0,x1,y0,y1;if(sd==="top"){x0=c.x+l0;x1=c.x+l1;y0=c.y+d0;y1=c.y+d1;}else if(sd==="bottom"){x0=c.x+l0;x1=c.x+l1;y0=c.y+c.h-d1;y1=c.y+c.h-d0;}else if(sd==="left"){y0=c.y+l0;y1=c.y+l1;x0=c.x+d0;x1=c.x+d1;}else{y0=c.y+l0;y1=c.y+l1;x0=c.x+c.w-d1;x1=c.x+c.w-d0;}return {x:x0,y:y0,w:x1-x0,h:y1-y0};};
  const t=c.u.t,bal=Dp*.1,main=Dp*.62;const beds=Array.from({length:t},()=>["BED",1]);const half=Math.ceil(t/2);
  const seq=[...beds.slice(0,half),["LIVING",1.7],["KIT",.8],...beds.slice(half)];const tw=seq.reduce((s,r)=>s+r[1],0);let out="";let l=3;const Lu=L-6;
  const rr=(r,lab,cls="")=>{out+=`<rect x="${r.x}" y="${r.y}" width="${Math.max(0,r.w)}" height="${Math.max(0,r.h)}" class="fp-room ${cls}"/>`;if(lab&&r.w>22&&r.h>14)out+=`<text x="${r.x+r.w/2}" y="${r.y+r.h/2+3}" class="fp-r" text-anchor="middle">${lab}</text>`;};
  rr(R(3,L-3,3,3+bal),"BALCONY","bal");
  seq.forEach(([k,wt],i)=>{const ln=Lu*wt/tw;const r=R(l,l+ln,3+bal,3+bal+main);rr(r,k==="BED"?(i===0?"MASTER":"BED"):k);
    const inner=R(l,l+ln,3+bal+main,Dp-3);if(k==="BED"&&i===0)rr(R(l,l+ln*.55,3+bal+main,Dp-3),"T","wet");else if(k==="KIT")rr(inner,"UTIL","wet");else if(k==="LIVING")rr(inner,"ENTRY","ent");else if(k==="BED"&&i%2===1)rr(R(l,l+ln*.5,3+bal+main,Dp-3),"T","wet");
    l+=ln;});
  return out;}
function planSVG(layoutK,units,W,D){
  const V=520,H=Math.round(V*Math.min(.9,Math.max(.55,D/W))),pad=26,w=V-pad*2,h=H-pad*2;
  let parts=[];
  if(layoutK==="twin"){const g=w*.12,bw=(w-g)/2;const a=units.filter((_,i)=>i%2===0),b=units.filter((_,i)=>i%2===1);[[a,pad],[b,pad+bw+g]].forEach(([us,x0])=>{if(us.length)parts.push({...cellsRect(x0,pad,bw,h,us),outline:[x0,pad,bw,h]});});
    parts.bridge={x:pad+bw,y:pad+h*.44,w:g,h:h*.12};}
  else if(layoutK==="court"){const r=.42,iw=w*r,ih=h*r,ix=pad+(w-iw)/2,iy=pad+(h-ih)/2;
    const bands=[{x:pad,y:pad,w,h:iy-pad,sd:"top"},{x:pad,y:iy+ih,w,h:pad+h-(iy+ih),sd:"bottom"},{x:pad,y:iy,w:ix-pad,h:ih,sd:"left"},{x:ix+iw,y:iy,w:pad+w-(ix+iw),h:ih,sd:"right"}];
    const areas=bands.map(b=>b.w*b.h),tot=areas.reduce((s,a)=>s+a,0);const n=units.length;let alloc=bands.map((b,i)=>Math.round(n*areas[i]/tot));let d=n-alloc.reduce((s,a)=>s+a,0);alloc[0]+=d;
    let k=0;const cells=[];bands.forEach((b,i)=>{const us=units.slice(k,k+alloc[i]);k+=alloc[i];if(!us.length)return;const tt=us.reduce((s,u)=>s+u.a,0);const horiz=b.w>=b.h;let c=horiz?b.x:b.y;us.forEach(u=>{const f=u.a/tt;if(horiz){cells.push({x:c,y:b.y,w:b.w*f,h:b.h,u,side:b.sd});c+=b.w*f;}else{cells.push({x:b.x,y:c,w:b.w,h:b.h*f,u,side:b.sd});c+=b.h*f;}});});
    parts.push({cells,cores:[{x:pad+4,y:pad+4,w:w*.1,h:h*.14},{x:pad+w-4-w*.1,y:pad+h-4-h*.14,w:w*.1,h:h*.14}],corr:null,outline:[pad,pad,w,h],court:[ix,iy,iw,ih]});}
  else if(layoutK==="linear"){const gh=h*.16,bh=h*.62,y0=pad+(h-bh-gh)/2;const tot=units.reduce((s,u)=>s+u.a,0);const cw=w*.08;let cx=pad+cw;const cells=[];units.forEach(u=>{const ww=(w-2*cw)*u.a/tot;cells.push({x:cx,y:y0,w:ww,h:bh,u,side:"top"});cx+=ww;});
    parts.push({cells,cores:[{x:pad,y:y0,w:cw,h:bh},{x:pad+w-cw,y:y0,w:cw,h:bh}],corr:{x:pad,y:y0+bh,w,h:gh},outline:[pad,y0,w,bh+gh],gallery:true});}
  else if(layoutK==="ell"){const t=h*.42;const A={x:pad,y:pad,w,h:t},B={x:pad+w-w*.36,y:pad+t,w:w*.36,h:h-t};const n=units.length,na=Math.ceil(n*.6),ua=units.slice(0,na),ub=units.slice(na);const cells=[];
    const ta=ua.reduce((s,u)=>s+u.a,0);let cx=A.x;ua.forEach(u=>{const ww=(A.w-B.w)*u.a/ta;cells.push({x:cx,y:A.y,w:ww,h:A.h,u,side:"top"});cx+=ww;});
    const tb=ub.reduce((s,u)=>s+u.a,0)||1;let cy=B.y;ub.forEach(u=>{const hh=B.h*u.a/tb;cells.push({x:B.x,y:cy,w:B.w,h:hh,u,side:"right"});cy+=hh;});
    parts.push({cells,cores:[{x:A.x+A.w-B.w,y:A.y,w:B.w,h:A.h}],corr:null,outline:[pad,pad,w,h],ell:[A,B]});}
  else parts.push({...cellsRect(pad,pad,w,h,units),outline:[pad,pad,w,h]});
  let s=`<svg viewBox="0 0 ${V} ${H}" role="img" aria-label="Schematic typical floor plan">`;
  s+=`<defs><pattern id="fpH" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="6" stroke="#3a342b" stroke-width="2"/></pattern></defs>`;
  parts.forEach(pt=>{const [ox,oy,ow,oh]=pt.outline;s+=`<rect x="${ox-6}" y="${oy-6}" width="${ow+12}" height="${oh+12}" fill="none" stroke="#3d3529" stroke-dasharray="3 4"/>`;
    if(pt.court){const [cx,cy,cw,ch]=pt.court;s+=`<rect x="${cx}" y="${cy}" width="${cw}" height="${ch}" fill="#1f2b20" stroke="#34503B"/><text x="${cx+cw/2}" y="${cy+ch/2+4}" class="fp-t2" text-anchor="middle">COURTYARD</text>`;}
    pt.cells.forEach((c,i)=>{const U=UNIT[c.u.t];s+=`<g class="fp-u" style="--d:${i*40}ms"><rect x="${c.x+2}" y="${c.y+2}" width="${Math.max(0,c.w-4)}" height="${Math.max(0,c.h-4)}" fill="${U.c}" fill-opacity=".12" stroke="${U.c}" stroke-width="1.4"/>`;
      s+=roomsSVG({...c,x:c.x+2,y:c.y+2,w:c.w-4,h:c.h-4});
      const tag=`${U.n} · ~${fmt(c.u.a)}`;const tw2=tag.length*5.6+14;const cxm=c.x+c.w/2,cym=c.y+c.h/2;
      if(c.w>tw2+6)s+=`<rect x="${cxm-tw2/2}" y="${cym-9}" width="${tw2}" height="18" rx="9" fill="#0f0d0b" stroke="${U.c}" stroke-width=".8"/><text x="${cxm}" y="${cym+4}" class="fp-tag" text-anchor="middle">${tag}</text>`;
      else s+=`<rect x="${cxm-17}" y="${cym-9}" width="34" height="18" rx="9" fill="#0f0d0b" stroke="${U.c}" stroke-width=".8"/><text x="${cxm}" y="${cym+4}" class="fp-tag" text-anchor="middle">${c.u.t}BHK</text>`;
      s+=`</g>`;});
    if(pt.corr)s+=`<rect x="${pt.corr.x+2}" y="${pt.corr.y}" width="${pt.corr.w-4}" height="${pt.corr.h}" fill="#15130f"/>`+(pt.gallery?`<text x="${pt.corr.x+pt.corr.w/2}" y="${pt.corr.y+pt.corr.h/2+3}" class="fp-t3" text-anchor="middle">OPEN GALLERY · CROSS-VENTILATION</text>`:"");
    pt.cores.forEach(c=>{s+=`<rect x="${c.x}" y="${c.y}" width="${c.w}" height="${c.h}" fill="url(#fpH)" stroke="#6a5e50"/><text x="${c.x+c.w/2}" y="${c.y+c.h/2+3}" class="fp-t3" text-anchor="middle">CORE</text>`;});});
  if(parts.bridge){const b=parts.bridge;s+=`<rect x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" fill="#15130f" stroke="#6a5e50" stroke-dasharray="2 3"/>`;}
  return s+`</svg>`;
}
let fpIdx=0;
function openPlans(){
  const id=selected;if(!id||!PLOTS[id]||!building)return;const p=PLOTS[id],T=TYPO[typo],L=LAYOUTS[layout],u=building.userData;
  const plateSq=u.placedSqft/T.floors,carpet=plateSq*EFF;const list=mixes(carpet);if(fpIdx>=list.length)fpIdx=0;
  const W=Math.max(p.dims[0],p.dims[1]),D=Math.min(p.dims[0],p.dims[1]);
  const m=list[fpIdx];const per=m.units.length;const counts={};m.units.forEach(x=>counts[x.t]=(counts[x.t]||0)+1);
  const el=$("#fp");
  el.innerHTML=`<div class="fp-card" role="dialog" aria-modal="false" aria-labelledby="fpT">
    <button class="pn-x" type="button" data-fpx aria-label="Close floor plans">×</button>
    <p class="pn-k"><i></i>Typical floor · Plot ${pad2(id)}</p>
    <h3 class="fp-h" id="fpT">${L.name} <em>${T.name}</em></h3>
    <p class="fp-sub">≈ ${fmt(plateSq)} sq ft per floor · ≈ ${fmt(carpet)} sq ft carpet at ~${Math.round(EFF*100)}% efficiency</p>
    <div class="fp-tabs" role="tablist">${list.map((v,i)=>`<button type="button" role="tab" aria-selected="${i===fpIdx}" data-fpi="${i}"><b>${v.name}</b><span>${v.units.length} flat${v.units.length>1?"s":""} / floor</span></button>`).join("")}</div>
    <div class="fp-plan">${planSVG(layout,m.units,W,D)}</div>
    <div class="fp-sum">
      <div><b>${per}</b><span>Flats per floor</span></div>
      <div><b>${per*T.floors}</b><span>Flats in ${T.floors} floors</span></div>
      <div class="fp-mix">${Object.keys(counts).sort().map(t=>`<span><i style="background:${UNIT[t].c}"></i>${counts[t]} × ${UNIT[t].n} · ~${fmt(m.units.find(x=>x.t==t).a)} sq ft</span>`).join("")}</div>
    </div>
    <ul class="fp-ergo">${ERGO[layout].map(x=>`<li>${x}</li>`).join("")}</ul>
    <p class="fp-note">${m.line}. Schematic only: carpet areas are indicative, and final plans depend on setbacks, parking, fire norms and approvals.</p>
  </div>`;
  el.hidden=false;stage.classList.add("has-fp");
  el.querySelector("[data-fpx]").addEventListener("click",closePlans);
  el.querySelectorAll("[data-fpi]").forEach(b=>b.addEventListener("click",()=>{fpIdx=+b.dataset.fpi;openPlans();}));
}
function closePlans(){const el=$("#fp");el.hidden=true;el.innerHTML="";stage.classList.remove("has-fp");}
addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("#fp").hidden){e.stopImmediatePropagation();closePlans();}},true);
function frameBuilding(){if(!building||!selected)return;const st=plotState[selected];const Hb=TYPO[typo].floors*3.2;const tgt=new THREE.Vector3(st.c[0],Hb*.45,st.c[1]);
  const dir=camera.position.clone().sub(controls.target);dir.y=0;if(dir.lengthSq()<1)dir.set(1,0,1);dir.normalize();const dist=Math.max(70,Hb*3.1);
  go(tgt.clone().add(dir.multiplyScalar(dist)).add(new THREE.Vector3(0,Hb*1.1+18,0)),tgt,1.2);}

