function flyTo(c){const tgt=new THREE.Vector3(c[0],0,c[1]);const off=camera.position.clone().sub(controls.target);off.setLength(Math.max(150,Math.min(off.length(),240)));if(off.y<70)off.y=70;go(tgt.clone().add(off),tgt,1.1);}
