cv.addEventListener("pointerdown",e=>{down=[e.clientX,e.clientY];tween=null;idle=false;});
cv.addEventListener("pointerup",e=>{if(down&&Math.hypot(e.clientX-down[0],e.clientY-down[1])<6){const id=pick(e);if(id)select(id);else if(selected)deselect();}down=null;});
cv.addEventListener("pointermove",e=>{if(e.pointerType!=="mouse"||e.buttons)return;const id=pick(e);const h=id&&PLOTS[id]?id:null;if(h!==hovered){const prev=hovered;hovered=h;if(prev)paint(prev);if(h)paint(h);}cv.classList.toggle("pointer",!!id);});
addEventListener("keydown",e=>{if(e.key==="Escape"){if(selected)deselect();else if(active)deactivate();}});

/* ================= scroll story ================= */
let storyP=0,storyAtActivate=-1,storyCurveP=null,storyCurveT=null,gateRing=null,storyGlow=false;
const CH_C=[.06,.27,.47,.67,.85];
function storyInit(){
  const [gx,gz]=gatePos,[dx,dz]=gateDir;const sg=(dx*(0-gx)+dz*(0-gz))>0?1:-1;const V=(x,y,z)=>new THREE.Vector3(x,y,z);
  const ph=isPhone();
  const P=[V(ph?420:300,ph?360:215,ph?390:250),V(gx-dx*sg*(ph?80:62),ph?24:17,gz-dz*sg*(ph?80:62)),V(ph?80:76,ph?22:16,ph?58:50),V(ph?-70:-50,ph?210:105,ph?-260:-200),V(ph?-220:-170,ph?230:135,ph?160:120),V(0,ph?640:450,.5)];
  const T=[V(0,0,8),V(gx+dx*sg*20,4,gz+dz*sg*20),V(48,2,-4),V(20,0,-50),V(-40,0,10),V(0,0,0)];
  storyCurveP=new THREE.CatmullRomCurve3(P,false,"centripetal",.5);storyCurveT=new THREE.CatmullRomCurve3(T,false,"centripetal",.5);
  gateRing=new THREE.Mesh(new THREE.RingGeometry(7,7.5,64),new THREE.MeshBasicMaterial({color:0xffd98a,transparent:true,opacity:0,depthWrite:false}));gateRing.rotation.x=-Math.PI/2;gateRing.position.set(gx,.8,gz);scene.add(gateRing);
  camera.position.copy(P[0]);controls.target.copy(T[0]);
  addEventListener("scroll",onStoryScroll,{passive:true});addEventListener("resize",onStoryScroll);onStoryScroll();
}
function onStoryScroll(){const len=storyLen();storyP=Math.max(0,Math.min(1,(scrollY-storyTop())/len));
  const chs=document.querySelectorAll(".ch");let cur=-1;if(storyP>=.93)cur=5;else{for(let i=0;i<5;i++){if(storyP<(i<4?(CH_C[i]+CH_C[i+1])/2:.93)){cur=i;break;}}}
  chs.forEach(c=>c.classList.toggle("on",+c.dataset.ch===cur));
  document.querySelectorAll(".ch-rail button").forEach((b,i)=>b.classList.toggle("on",i===cur));
  stage.classList.toggle("at-end",storyP>=.93);
  if(active&&storyAtActivate>=0&&Math.abs(storyP-storyAtActivate)>.04&&!document.fullscreenElement)deactivate();
}
const KU=[.06,.27,.47,.67,.85,1];
function curveU(u){if(u<=KU[0])return 0;for(let j=0;j<5;j++){if(u<=KU[j+1]){const l=(u-KU[j])/(KU[j+1]-KU[j]);const e=l<=.12?0:l>=.88?1:((x)=>x*x*(3-2*x))((l-.12)/.76);return (j+e)/5;}}return 1;}
function storyFrame(dt,now){if(!storyCurveP)return;const u=reduce?1:storyP;const cu=curveU(u);const k=reduce?1:1-Math.exp(-dt*4.2);
  camera.position.lerp(storyCurveP.getPoint(cu),k);controls.target.lerp(storyCurveT.getPoint(cu),k);
  const w=CH_C.map(c=>Math.max(0,1-Math.abs(u-c)/.13));const base=MOODS[mood];
  M.lamp.emissiveIntensity=base.lamp*(1+2.2*w[2]);M.pool.opacity=base.pool+.14*w[2];
  M.green.emissive.setHex(0x2f4a22);M.green.emissiveIntensity=.9*w[3];
  if(gateRing){gateRing.material.opacity=.85*w[1];const sc=1+.18*Math.sin(now*.004);gateRing.scale.set(sc,sc,sc);}
  const g=w[4]>.35;if(g!==storyGlow){storyGlow=g;repaintAll();}
}
/* ================= post-processing: HDR → bloom → ACES grade, vignette, grain ================= */
let composer=null,bloom=null,grade=null;
const GRADE={uniforms:{tDiffuse:{value:null},exposure:{value:1},vign:{value:.8},time:{value:0},grain:{value:.03}},
  vertexShader:"varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}",
  fragmentShader:"uniform sampler2D tDiffuse;uniform float exposure,vign,time,grain;varying vec2 vUv;vec3 aces(vec3 x){return clamp((x*(2.51*x+.03))/(x*(2.43*x+.59)+.14),0.,1.);}float rnd(vec2 p){return fract(sin(dot(p,vec2(12.9898,78.233)))*43758.5453);}void main(){vec3 c=texture2D(tDiffuse,vUv).rgb*exposure;c=aces(c);c=pow(c,vec3(1./2.2));c=mix(c,c*vec3(1.035,1.0,.955),.6);float d=distance(vUv,vec2(.5));c*=mix(1.,smoothstep(.95,.28,d),vign*.55);c+=(rnd(vUv*vec2(1731.,977.)+fract(time))-.5)*grain;gl_FragColor=vec4(c,1.);}"};
function setupPost(){if(window.noWebGL||!THREE.EffectComposer)return;try{const w=stage.clientWidth||800,h=stage.clientHeight||600;
  const rt=new THREE.WebGLRenderTarget(w,h,{type:THREE.HalfFloatType,samples:(renderer.capabilities.isWebGL2&&!isPhone())?4:0});
  composer=new THREE.EffectComposer(renderer,rt);composer.setPixelRatio(renderer.getPixelRatio());composer.addPass(new THREE.RenderPass(scene,camera));
  bloom=new THREE.UnrealBloomPass(new THREE.Vector2(w,h),.5,.5,.8);composer.addPass(bloom);grade=new THREE.ShaderPass(GRADE);composer.addPass(grade);
  renderer.toneMapping=THREE.NoToneMapping;const pm=new THREE.PMREMGenerator(renderer);scene.environment=pm.fromScene(new THREE.RoomEnvironment(),.04).texture;composer.setSize(w,h);
  }catch(e){console.warn("post-processing unavailable",e);composer=null;renderer.toneMapping=THREE.ACESFilmicToneMapping;}}
/* ================= loop ================= */
let viewerVisible=false;
new IntersectionObserver(entries=>{const en=entries[0];viewerVisible=en.isIntersecting;if(en.intersectionRatio<.2&&active&&!document.fullscreenElement)deactivate();},{threshold:[0,.2,.5]}).observe(stage);
let vo={x:0,y:0};
function resize(){const w=stage.clientWidth,h=stage.clientHeight;renderer.setSize(w,h,false);if(composer)composer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();}
const needle=$("#needle"),tmp=new THREE.Vector3();let last=performance.now();
function loop(now){requestAnimationFrame(loop);if(!viewerVisible||document.hidden){last=now;return;}const dt=Math.min(.05,(now-last)/1000);last=now;
  if(tween){tween.t=Math.min(1,tween.t+dt/tween.dur);const e=tween.t<.5?4*tween.t**3:1-Math.pow(-2*tween.t+2,3)/2;controls.target.lerpVectors(tween.fromT,tween.toT,e);camera.position.lerpVectors(tween.fromP,tween.toP,e);if(tween.t>=1){const th=tween.then;tween=null;if(th)th();}}
  else if(!active){storyFrame(dt,now);}
  for(const k in plotState){const s=plotState[k];s.lift+=(s.target-s.lift)*(reduce?1:.14);plotMeshes[k].position.y=s.lift;}
  if(building&&selected)building.position.y=plotState[selected].lift;
  {const w=stage.clientWidth,h=stage.clientHeight,open=!$("#panel").classList.contains("away");const tx=open&&!isPhone()?Math.min(200,w*.15):0,ty=open&&isPhone()?h*.18:0;
   vo.x+=(tx-vo.x)*(reduce?1:.1);vo.y+=(ty-vo.y)*(reduce?1:.1);if(Math.abs(vo.x)+Math.abs(vo.y)<.5)camera.clearViewOffset();else camera.setViewOffset(w,h,vo.x,vo.y,w,h);}
  controls.update();if(composer){grade.uniforms.time.value=now*.001;composer.render();}else renderer.render(scene,camera);
  needle.style.transform=`rotate(${controls.getAzimuthalAngle()*180/Math.PI}deg)`;
  const w=cv.clientWidth,h=cv.clientHeight;tagEls.forEach(t=>{tmp.copy(t.v).project(camera);const vis=tmp.z<1&&Math.abs(tmp.x)<1.05&&Math.abs(tmp.y)<1.05;t.el.classList.toggle("hidden",!vis||!!t.off);if(vis){t.el.style.left=((tmp.x+1)/2*w)+"px";t.el.style.top=((1-tmp.y)/2*h)+"px";}});
}
document.fonts.load("500 92px 'Cormorant Garamond'").catch(()=>{}).finally(()=>{
  build();buildCinema();setupPost();resize();controls.enabled=false;setTime("gallery");storyInit();
  const ld=document.getElementById("viewerLoading");if(window.noWebGL){ld.classList.add("fail");}else ld.hidden=true;repaintAll();
  const m=location.hash.match(/^#plot(\d{1,2})$/);if(m&&PLOTS[m[1]]){activate(false);select(m[1]);}
  requestAnimationFrame(loop);window.aasthaReady=!window.noWebGL;
});
